        if (0, c) in markers and (h - 1, c) in markers:
            line.update((r, c) for r in range(h))

    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            hit = False
            while stack:
                rr, cc = stack.pop()
                component.append((rr, cc))
                hit |= (rr, cc) in line
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
